import { Button, DownloadButton, cn } from '@gntik-ai/ui';
import { observeTheme, currentTheme } from '@gntik-ai/tokens/runtime';
import { Check, Copy, X, ZoomIn, ZoomOut, RotateCcw } from 'lucide-react';
import { useEffect, useId, useState } from 'react';
import { CodeBlock } from '../markdown/CodeBlock';
import { useChatI18n } from '../utils/i18n';
import { useCopy } from '../utils/useCopy';
import { renderMermaid } from './loadMermaid';
import { themeVariables } from './themeVariables';
import { useDiagramViewport } from './useDiagramViewport';
import { mermaidDiagramStyles as s } from './mermaidDiagram.variants';

export type DiagramView = 'diagram' | 'code';
export interface MermaidDiagramProps {
  code: string;
  streaming?: boolean;
  defaultView?: DiagramView;
  onViewChange?: (view: DiagramView) => void;
  label?: string;
  className?: string;
}

export function MermaidDiagram({
  code,
  streaming = false,
  defaultView = 'diagram',
  onViewChange,
  label,
  className,
}: MermaidDiagramProps) {
  const { tc, t } = useChatI18n();
  const { copied, status, copy } = useCopy();
  const viewport = useDiagramViewport();
  const id = useId().replace(/[^a-zA-Z0-9]/g, '');
  const [result, setResult] = useState<{ code: string; theme: string; svg?: string; failed?: boolean }>();
  const [theme, setTheme] = useState(currentTheme);
  const [view, setView] = useState(defaultView);
  useEffect(() => observeTheme(setTheme), []);
  useEffect(() => {
    let active = true;
    if (!streaming) {
      void renderMermaid(code, id, themeVariables(), () => active)
        .then((svg) => {
          if (active && svg) setResult({ code, theme, svg });
        })
        .catch(() => {
          if (active) setResult({ code, theme, failed: true });
        });
    }
    return () => {
      active = false;
    };
  }, [code, id, streaming, theme]);
  const current = !streaming && result?.code === code && result.theme === theme ? result : undefined;
  const svg = current?.svg ?? '';
  const failed = current?.failed ?? false;
  const showingDiagram = !streaming && !failed && !!svg && view === 'diagram';
  const changeView = (next: DiagramView) => {
    if (view === next) return;
    setView(next);
    onViewChange?.(next);
  };
  return (
    <figure aria-label={label ?? tc('chat.diagram')} className={cn(s.root, className)}>
      <div className={s.toolbar}>
        <Button
          size="sm"
          variant="ghost"
          aria-pressed={showingDiagram}
          disabled={!svg || streaming || failed}
          aria-label={tc('chat.showDiagram')}
          onClick={() => changeView('diagram')}
        >
          {tc('chat.diagram')}
        </Button>
        <Button
          size="sm"
          variant="ghost"
          aria-pressed={!showingDiagram}
          aria-label={tc('chat.showCode')}
          onClick={() => changeView('code')}
        >
          {tc('chat.showCode')}
        </Button>
        {showingDiagram && (
          <Button
            size="sm"
            variant="ghost"
            icon={status === 'failed' ? X : copied ? Check : Copy}
            aria-label={status === 'failed' ? t('common.copyFailed') : t('chat.copyCode')}
            onClick={() => void copy(code)}
          >
            {status === 'failed' ? t('common.copyFailed') : copied ? t('common.copied') : t('common.copy')}
          </Button>
        )}
        <DownloadButton
          size="sm"
          variant="ghost"
          data={svg}
          fileName="diagram.svg"
          mimeType="image/svg+xml"
          disabled={!svg || streaming || failed}
        >
          {tc('chat.downloadSvg')}
        </DownloadButton>
        <Button
          size="sm"
          variant="ghost"
          icon={ZoomIn}
          aria-label={tc('chat.zoomIn')}
          disabled={!showingDiagram}
          onClick={() => viewport.zoom(0.2)}
        />
        <Button
          size="sm"
          variant="ghost"
          icon={ZoomOut}
          aria-label={tc('chat.zoomOut')}
          disabled={!showingDiagram}
          onClick={() => viewport.zoom(-0.2)}
        />
        <Button
          size="sm"
          variant="ghost"
          icon={RotateCcw}
          aria-label={tc('chat.resetZoom')}
          disabled={!showingDiagram}
          onClick={viewport.reset}
        />
      </div>
      {showingDiagram ? (
        <div
          role="region"
          aria-label={label ?? tc('chat.diagram')}
          tabIndex={0}
          className={s.viewport}
          {...viewport.handlers}
        >
          <div
            className={s.canvas}
            style={{ transform: viewport.transform }}
            dangerouslySetInnerHTML={{ __html: svg }}
          />
        </div>
      ) : (
        <CodeBlock code={code} language="mermaid" />
      )}
      {!streaming && (failed || !svg) && (
        <p role="status" className={s.note}>
          {tc(failed ? 'chat.diagramFailed' : 'chat.renderingDiagram')}
        </p>
      )}
    </figure>
  );
}

import { createElement } from 'react';
import type { MarkdownCodeRendererProps } from '../markdown';
import { MermaidDiagram } from './MermaidDiagram';

export { MermaidDiagram, type MermaidDiagramProps, type DiagramView } from './MermaidDiagram';
function MermaidCodeRenderer({ code, complete }: MarkdownCodeRendererProps) {
  return createElement(MermaidDiagram, { code, streaming: !complete });
}
/** Opt-in fence renderer. Closed fences render even while sibling prose streams. */
export const mermaidCodeRenderers = { mermaid: MermaidCodeRenderer };

import type { Mermaid } from 'mermaid';
import { sanitizeSvg } from './sanitizeSvg';

let loading: Promise<Mermaid> | undefined;
/** The optional peer is requested only by a mounted, complete diagram. */
export function loadMermaid(): Promise<Mermaid> {
  return (loading ??= import('mermaid').then((module) => module.default));
}

// Mermaid's initialise/render pair uses global configuration. Serialise it so
// sibling diagrams cannot overwrite each other's theme while rendering awaits.
let pending: Promise<unknown> = Promise.resolve();
let sequence = 0;
export function renderMermaid(
  code: string,
  id: string,
  variables: Record<string, string>,
  active: () => boolean,
): Promise<string | undefined> {
  const request = pending.then(async () => {
    if (!active()) return;
    const mermaid = await loadMermaid();
    if (!active()) return;
    mermaid.initialize({
      startOnLoad: false,
      securityLevel: 'strict',
      theme: 'base',
      themeVariables: variables,
      htmlLabels: false,
      suppressErrorRendering: true,
      logLevel: 'fatal',
      // Untrusted frontmatter/directives cannot override the renderer's policy.
      secure: [
        'secure',
        'securityLevel',
        'startOnLoad',
        'maxTextSize',
        'maxEdges',
        'suppressErrorRendering',
        'htmlLabels',
        'theme',
        'themeVariables',
        'themeCSS',
        'dompurifyConfig',
        'flowchart',
        'fontFamily',
        'logLevel',
      ],
    });
    const scratch = document.createElement('div');
    scratch.className = 'fixed start-0 top-0 invisible pointer-events-none';
    scratch.inert = true;
    scratch.setAttribute('aria-hidden', 'true');
    document.body.append(scratch);
    try {
      const result = await mermaid.render(`diagram${id}-${++sequence}`, code, scratch);
      return sanitizeSvg(result.svg);
    } finally {
      scratch.remove();
    }
  });
  pending = request.catch(() => {});
  return request;
}

export const mermaidDiagramStyles = {
  root: 'my-3 overflow-hidden rounded-lg border border-border bg-background text-foreground',
  toolbar: 'flex flex-wrap items-center gap-1 border-b border-border p-2',
  viewport: 'relative overflow-hidden p-4 focus-ring touch-none cursor-grab active:cursor-grabbing',
  canvas: 'origin-center [&>svg]:mx-auto [&>svg]:h-auto [&>svg]:max-w-full',
  note: 'px-3 pb-3 text-sm text-muted-foreground',
};

const SVG_NAMESPACE = 'http://www.w3.org/2000/svg';
// Static SVG only: no HTML integration points, external resources or animation.
const elements = new Set(
  'svg g defs style title desc path rect circle ellipse line polyline polygon text tspan textPath marker clipPath mask pattern linearGradient radialGradient stop symbol use a'
    .toLowerCase()
    .split(' '),
);
const attributes = new Set(
  'id class style role viewBox width height x y x1 y1 x2 y2 dx dy cx cy r rx ry d points transform fill fill-opacity fill-rule stroke stroke-width stroke-opacity stroke-dasharray stroke-dashoffset stroke-linecap stroke-linejoin stroke-miterlimit opacity font-family font-size font-weight font-style text-anchor dominant-baseline alignment-baseline textLength lengthAdjust marker-start marker-mid marker-end markerWidth markerHeight markerUnits refX refY orient clip-path clipPathUnits mask maskUnits maskContentUnits patternUnits patternContentUnits patternTransform preserveAspectRatio gradientUnits gradientTransform offset stop-color stop-opacity href xmlns xmlns:xlink xlink:href color overflow visibility direction unicode-bidi'
    .toLowerCase()
    .split(' '),
);

function safeCss(value: string): boolean {
  // CSS escapes/comments can disguise a protocol. Only local fragment URLs survive.
  // The child combinator (>) is used by Mermaid's sequence and architecture styles.
  const withoutFragments = value.replace(/url\(\s*(['"]?)#[\w.-]+\1\s*\)/gi, '');
  return !/[\\@<]|\/\*|(?:expression|image-set|src)\s*\(|(?:java|vb)script\s*:|(?:https?|data):|url\s*\(/i.test(
    withoutFragments,
  );
}

function staticCss(value: string): string {
  // Mermaid includes keyframes even for static graphs. Discard those balanced
  // blocks, preserving the surrounding token-based styles. Fail closed on CSS
  // escapes, other at-rules or malformed blocks rather than interpreting them.
  const keyframes = /@(?:-[a-z]+-)?keyframes\b[^{}]*\{/gi;
  let match: RegExpExecArray | null;
  while ((match = keyframes.exec(value))) {
    let depth = 1;
    let end = keyframes.lastIndex;
    for (; end < value.length && depth; end++) {
      if (value[end] === '{') depth++;
      if (value[end] === '}') depth--;
    }
    if (depth) return '';
    value = value.slice(0, match.index) + value.slice(end);
    keyframes.lastIndex = match.index;
  }
  if (!safeCss(value)) return '';
  return value.replace(/\b(?:animation|transition)(?:-[a-z-]+)?\s*:[^;{}]*(?:;|(?=}))/gi, '');
}

/** Defence in depth after Mermaid's strict-mode sanitiser. Never receives raw source. */
export function sanitizeSvg(svg: string): string {
  const parsed = new DOMParser().parseFromString(svg, 'image/svg+xml');
  const root = parsed.documentElement;
  if (
    parsed.doctype ||
    parsed.querySelector('parsererror') ||
    root.localName !== 'svg' ||
    root.namespaceURI !== SVG_NAMESPACE
  ) {
    throw new Error('Invalid SVG');
  }
  for (const element of [root, ...root.querySelectorAll('*')]) {
    if (element.namespaceURI !== SVG_NAMESPACE || !elements.has(element.localName.toLowerCase())) {
      element.remove();
      continue;
    }
    if (element.localName.toLowerCase() === 'style') {
      const css = staticCss(element.textContent ?? '');
      if (!css) {
        element.remove();
        continue;
      }
      element.textContent = css;
    }
    for (const attribute of [...element.attributes]) {
      const name = attribute.name.toLowerCase();
      const value = name === 'style' ? staticCss(attribute.value) : attribute.value;
      if (name === 'style') attribute.value = value;
      const compact = Array.from(value)
        .filter((c) => c.charCodeAt(0) > 0x20 && !/\s/.test(c))
        .join('');
      if (
        name.startsWith('on') ||
        (!attributes.has(name) && !/^aria-[a-z-]+$/.test(name)) ||
        (/href$/.test(name) && !/^#[\w.-]+$/.test(value)) ||
        /(?:javascript|vbscript):/i.test(compact) ||
        (!safeCss(value) && name !== 'xmlns' && name !== 'xmlns:xlink')
      )
        element.removeAttributeNode(attribute);
    }
  }
  return new XMLSerializer().serializeToString(root);
}

import { useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';

const initial = { scale: 1, x: 0, y: 0 };
export function useDiagramViewport() {
  const [position, setPosition] = useState(initial);
  const drag = useRef<{ id: number; x: number; y: number; panX: number; panY: number } | null>(null);
  const zoom = (delta: number) =>
    setPosition((p) => ({ ...p, scale: Math.max(0.2, Math.min(4, Math.round((p.scale + delta) * 10) / 10)) }));
  const reset = () => setPosition(initial);
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.target !== event.currentTarget || event.altKey || event.ctrlKey || event.metaKey) return;
    switch (event.key) {
      case '+':
      case '=':
        zoom(0.2);
        break;
      case '-':
        zoom(-0.2);
        break;
      case '0':
        reset();
        break;
      case 'ArrowLeft':
        setPosition((p) => ({ ...p, x: p.x - 24 }));
        break;
      case 'ArrowRight':
        setPosition((p) => ({ ...p, x: p.x + 24 }));
        break;
      case 'ArrowUp':
        setPosition((p) => ({ ...p, y: p.y - 24 }));
        break;
      case 'ArrowDown':
        setPosition((p) => ({ ...p, y: p.y + 24 }));
        break;
      default:
        return;
    }
    event.preventDefault();
  };
  const stop = () => {
    drag.current = null;
  };
  return {
    zoom,
    reset,
    transform: `translate(${position.x}px, ${position.y}px) scale(${position.scale})`,
    handlers: {
      onKeyDown,
      onPointerDown(event: PointerEvent<HTMLDivElement>) {
        if (event.button !== 0) return;
        event.currentTarget.focus();
        event.currentTarget.setPointerCapture?.(event.pointerId);
        drag.current = { id: event.pointerId, x: event.clientX, y: event.clientY, panX: position.x, panY: position.y };
        event.preventDefault();
      },
      onPointerMove(event: PointerEvent<HTMLDivElement>) {
        const start = drag.current;
        if (!start || start.id !== event.pointerId) return;
        setPosition((p) => ({
          ...p,
          x: start.panX + event.clientX - start.x,
          y: start.panY + event.clientY - start.y,
        }));
      },
      onPointerUp: stop,
      onPointerCancel: stop,
      onLostPointerCapture: stop,
    },
  };
}

import { useClipboard } from '@gntik-ai/ui';
import { useCallback } from 'react';

/** Copies text with shared fallback support and the chat's 1600ms feedback duration. */
export function useCopy(resetMs = 1600) {
  const { status, copied, copy: copyText } = useClipboard({ timeout: resetMs });
  const copy = useCallback(
    async (text: string) => {
      await copyText(text);
    },
    [copyText],
  );
  return { status, copied, copy };
}
